"""Check renderer transport against every original generated byte and run guards."""
from pathlib import Path
import importlib.util,json
E=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('rigidity_transport_checks_common',E/'common.py')
common=importlib.util.module_from_spec(spec);spec.loader.exec_module(common)

def main():
 stage=common.S/'transport_checks';stage.mkdir()
 commands={
  'table_guards':common.PREFIX+['-m','unittest','discover','-s','tests','-p','test_inten_local_rigidity_tables.py','-v'],
  'complete_regeneration':common.PREFIX+[str(E/'report_docs.py')],
  'whitespace':['git','diff','--check'],
 }
 codes={name:common.run(name,command,stage) for name,command in commands.items()}
 try:
  protocol=common.read(E/'table_transport_protocol.json')
  packer=common.module('rigidity_transport_check_reader',E/'pack_tables.py')
  for name,meta in protocol['preserved_raw'].items():
   data=packer.read_file(name)
   import hashlib
   assert len(data)==meta['bytes'] and hashlib.sha256(data).hexdigest()==meta['sha256'],name
  # New transport does not alter any original mathematical or test source.
  for name in ('analyze.py','rigidity.py','report_io.py','common.py'):
   path=E/name
   assert common.git('show','6404d6bc:'+str(path.relative_to(common.W)))==path.read_text().strip(),name
  common.write(stage/'roundtrip.json',dict(exit_code=0,all_original_generated_bytes_exact=True,mathematical_producer_unchanged_from='6404d6bc',raw_bindings=protocol['preserved_raw']))
  codes['roundtrip']=0
 except Exception as error:
  common.write(stage/'roundtrip.json',dict(exit_code=1,error=str(error)));codes['roundtrip']=1
 code=0 if all(v==0 for v in codes.values()) else 1
 common.write(stage/'result.json',dict(exit_code=code,commands=codes))
 common.module('rigidity_transport_checks_archive',common.P/'archive.py').archive(stage,E/'checks/regeneration_transport')
 return code
if __name__=='__main__':raise SystemExit(main())
